import { GoogleGenAI, Type } from "@google/genai";

interface Env {
  API_KEY: string;
}

export const onRequestPost = async (context: any) => {
  try {
    if (typeof process === 'undefined') {
      (globalThis as any).process = { env: {} };
    }

    const { request, env } = context;
    const apiKey = env.API_KEY || (typeof process !== 'undefined' ? process.env.API_KEY : null);

    if (!apiKey) {
      return new Response(JSON.stringify({ error: "Server Configuration Error: API Key missing." }), { 
        status: 500,
        headers: { "Content-Type": "application/json" }
      });
    }

    const { mode, industry, city, companyName, excludeNames } = await request.json();

    if (mode === 'lookup') {
        if (!companyName) return new Response(JSON.stringify({ error: "Company Name is required for lookup" }), { status: 400 });
    } else {
        if (!industry || !city) return new Response(JSON.stringify({ error: "Industry and City are required" }), { status: 400 });
    }

    const ai = new GoogleGenAI({ apiKey: apiKey });
    const model = 'gemini-3-flash-preview';

    const exclusionList = excludeNames && excludeNames.length > 0 ? excludeNames.join(', ') : "None";

    const systemInstruction = `
      You are an expert Lead Generation AI agent.
      CORE DIRECTIVE: Prioritize finding CONTACT INFORMATION (Phone, Email, Social Links).

      SEARCH RULES:
      1. Use the googleSearch tool to find the company website, linkedin, and contact pages.
      2. If a direct email is missing, look for generic ones (info@, hello@).
      3. Do not return "N/A" unless you have verified it does not exist.
      4. Ensure all URLs are full and valid (https://).
    `;

    let prompt = '';
    if (mode === 'lookup') {
        prompt = `Target: "${companyName}" in "${city || 'any location'}". Find verified contact details, key needs, and social profiles.`;
    } else {
        prompt = `Find 5 ACTIVE ${industry} companies in ${city}. Exclude: ${exclusionList}. For every lead, find specific contact info and key business needs.`;
    }

    // Strict Schema Definition
    const schema = {
      type: Type.OBJECT,
      properties: {
        leads: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              website: { type: Type.STRING },
              location: { type: Type.STRING },
              description: { type: Type.STRING },
              needs: { 
                type: Type.ARRAY, 
                items: { type: Type.STRING } 
              },
              heroProduct: { type: Type.STRING },
              phone: { type: Type.STRING },
              email: { type: Type.STRING },
              socials: { type: Type.STRING, description: "Space separated full URLs" },
              hotScore: { type: Type.INTEGER },
              signals: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    type: { type: Type.STRING },
                    text: { type: Type.STRING },
                    confidence: { type: Type.STRING, enum: ["High", "Medium", "Low"] }
                  },
                  required: ["type", "text", "confidence"]
                }
              }
            },
            required: ["name", "website", "description", "hotScore", "email"]
          }
        }
      },
      required: ["leads"]
    };

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0.4,
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: schema
      },
    });

    // With responseSchema, response.text is guaranteed to be valid JSON structure
    let data;
    try {
        data = JSON.parse(response.text || "{}");
    } catch (e) {
        // Fallback for extremely rare edge cases
        console.error("JSON Parse Error:", response.text);
        throw new Error("Invalid JSON response from AI");
    }

    const leads = (data.leads || []).map((lead: any, index: number) => ({
        ...lead,
        id: `gen-${Date.now()}-${index}`,
        status: 'New',
        recentWork: lead.description, 
        website: lead.website || "N/A",
        phone: lead.phone || "N/A",
        email: lead.email || "N/A",
        socials: lead.socials || "N/A",
        signals: lead.signals || [],
        location: lead.location || city
    }));

    // Extract Grounding Chunks (Sources)
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sources = groundingChunks
        .map((chunk: any) => ({
            title: chunk.web?.title || "Web Source",
            uri: chunk.web?.uri
        }))
        .filter((s: any) => s.uri)
        .filter((v: any, i: number, a: any[]) => a.findIndex((t: any) => (t.uri === v.uri)) === i);

    return new Response(JSON.stringify({ leads, sources }), {
      status: 200,
      headers: { "Content-Type": "application/json" }
    });

  } catch (error: any) {
    console.error("Leads API Critical Error:", error);
    return new Response(JSON.stringify({ error: error.message || "Unknown Server Error" }), { 
        status: 500,
        headers: { "Content-Type": "application/json" }
    });
  }
};

import { GoogleGenAI, Type } from "@google/genai";

interface Env {
  API_KEY: string;
}

export const onRequestPost = async (context: any) => {
  try {
    if (typeof process === 'undefined') {
      (globalThis as any).process = { env: {} };
    }

    const { request, env } = context;
    const apiKey = env.API_KEY || (typeof process !== 'undefined' ? process.env.API_KEY : null);

    if (!apiKey) {
      return new Response(JSON.stringify({ error: "API Key not configured" }), {
        status: 500,
        headers: { "Content-Type": "application/json" },
      });
    }

    const { companyName, industry, userSkills, tone, companySignals, format = 'email' } = await request.json();

    const ai = new GoogleGenAI({ apiKey: apiKey });
    const model = 'gemini-3-flash-preview';

    let contextStr = "";
    if (companySignals && companySignals.length > 0) {
        contextStr = `COMPANY FACTS:\n${companySignals.join('\n')}\n`;
    }

    let specificInstructions = "";
    if (format === 'linkedin_connect') {
      specificInstructions = `
      FORMAT: LinkedIn Connection Request
      LENGTH: STRICTLY UNDER 300 CHARACTERS.
      SUBJECT LINE: Return an empty string "".
      STYLE: Casual, direct, mention the specific company fact.
      `;
    } else if (format === 'linkedin_inmail') {
      specificInstructions = `
      FORMAT: LinkedIn InMail
      LENGTH: Under 150 words.
      SUBJECT LINE: Required. Professional and catchy.
      STYLE: Conversational B2B.
      `;
    } else {
      specificInstructions = `
      FORMAT: Cold Email
      LENGTH: Under 100 words.
      SUBJECT LINE: Required. Intriguing.
      STYLE: ${tone}
      `;
    }

    const prompt = `
      Target: ${companyName} (${industry})
      My Skills: ${userSkills}
      ${contextStr}
      ${specificInstructions}

      Generate 3 variations:
      1. Evidence-Based (Lead with facts)
      2. Solution-Focused (Lead with value)
      3. Low-Friction (Short ask)
    `;

    const systemInstruction = `
      You are an elite B2B sales copywriter.
      1. Reference provided company facts.
      2. No hashtags.
      3. No buzzwords like "delve", "tapestry", "unlock".
      4. If format is 'linkedin_connect', the body MUST be < 300 chars.
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: { parts: [{ text: prompt }] },
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            pitches: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  angle: { type: Type.STRING },
                  subject: { type: Type.STRING },
                  body: { type: Type.STRING },
                },
                required: ["angle", "subject", "body"],
              },
            },
          },
          required: ["pitches"],
        },
        temperature: 0.7,
      },
    });

    const data = JSON.parse(response.text || "{}");

    return new Response(JSON.stringify(data), {
      status: 200,
      headers: { "Content-Type": "application/json" },
    });

  } catch (error: any) {
    console.error("Backend Pitch Error:", error);
    return new Response(JSON.stringify({ error: error.message }), {
      status: 500,
      headers: { "Content-Type": "application/json" },
    });
  }
};

import React, { useState } from 'react';
import { Target, Send, Loader2, Sparkles, Copy, Check, Bot, Phone, Mail, Award, Globe, Linkedin, Twitter, Facebook, Instagram, Youtube, Link as LinkIcon, Zap, TrendingUp, DollarSign, Newspaper, Edit3, Bookmark, ShieldCheck, MapPin, Briefcase, UserPlus } from 'lucide-react';
import { Company, Pitch } from '../types';
import { generatePitch } from '../services/geminiService';

interface IntelligencePaneProps {
  company: Company | null;
  onToggleSave: () => void;
  isSaved: boolean;
}

type Tab = 'overview' | 'insights' | 'outreach';
type PitchFormat = 'email' | 'linkedin_connect' | 'linkedin_inmail';

export const IntelligencePane: React.FC<IntelligencePaneProps> = ({ company, onToggleSave, isSaved }) => {
  const [activeTab, setActiveTab] = useState<Tab>('overview');
  const [skills, setSkills] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedPitches, setGeneratedPitches] = useState<Pitch[]>([]);
  const [activePitchIndex, setActivePitchIndex] = useState(0);
  const [copied, setCopied] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [pitchFormat, setPitchFormat] = useState<PitchFormat>('email');

  React.useEffect(() => {
    setGeneratedPitches([]);
    setActivePitchIndex(0);
    setIsEditing(false);
    setActiveTab('overview');
  }, [company?.id]);

  const handleFormatChange = (format: PitchFormat) => {
    setPitchFormat(format);
    setGeneratedPitches([]);
    setActivePitchIndex(0);
    setIsEditing(false);
  };

  const handleGenerate = async () => {
    if (!company || !skills) return;

    setIsGenerating(true);
    setGeneratedPitches([]);
    setActivePitchIndex(0);

    try {
      const signalContext = company.signals.map(s => `${s.type}: ${s.text}`);

      const results = await generatePitch({
        companyName: company.name,
        industry: company.industry,
        userSkills: skills,
        tone: 'Professional',
        companySignals: signalContext,
        format: pitchFormat
      });
      setGeneratedPitches(results);
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const getSignalIcon = (type: string) => {
    const t = type.toLowerCase();
    if (t.includes('fund') || t.includes('money')) return <DollarSign className="w-3 h-3 text-emerald-500" />;
    if (t.includes('hir') || t.includes('team') || t.includes('growth')) return <TrendingUp className="w-3 h-3 text-blue-500" />;
    if (t.includes('news') || t.includes('press')) return <Newspaper className="w-3 h-3 text-purple-500" />;
    if (t.includes('loc') || t.includes('hq')) return <MapPin className="w-3 h-3 text-orange-500" />;
    return <ShieldCheck className="w-3 h-3 text-accent" />;
  };

  const getSocialLinks = () => {
    if (!company || !company.socials || company.socials === 'N/A' || company.socials === 'None') return [];

    return company.socials
      .split(/[\s,\n]+/)
      .map(s => s.trim())
      .filter(s => s.length > 0 && !s.toLowerCase().includes('n/a'))
      .map((rawLink, index) => {
        let url = rawLink.replace(/[\[\]()]/g, '');
        if (!url.startsWith('http')) url = `https://${url}`;
        if (!url.includes('.') || url.length < 8) return null;

        let icon = <LinkIcon className="w-4 h-4" />;
        const lowerUrl = url.toLowerCase();

        if (lowerUrl.includes('linkedin')) icon = <Linkedin className="w-4 h-4" />;
        else if (lowerUrl.includes('twitter') || lowerUrl.includes('x.com')) icon = <Twitter className="w-4 h-4" />;
        else if (lowerUrl.includes('facebook')) icon = <Facebook className="w-4 h-4" />;
        else if (lowerUrl.includes('instagram')) icon = <Instagram className="w-4 h-4" />;
        else if (lowerUrl.includes('youtube')) icon = <Youtube className="w-4 h-4" />;

        return { url, icon, key: index };
      })
      .filter((link): link is { url: string; icon: React.ReactElement; key: number } => link !== null);
  };

  if (!company) {
    return (
