import React, { useEffect, useRef, useState } from 'react';
import { Mic, X, Activity, Volume2 } from 'lucide-react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { Company } from '../types';

interface VoiceModeProps {
  isActive: boolean;
  onClose: () => void;
  contextCompany: Company | null;
}

export const VoiceMode: React.FC<VoiceModeProps> = ({ isActive, onClose, contextCompany }) => {
  const [status, setStatus] = useState<'connecting' | 'listening' | 'speaking' | 'error'>('connecting');
  const [volumeLevel, setVolumeLevel] = useState(0);

  // Refs for Audio Handling
  const audioContextRef = useRef<AudioContext | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);
  const sourceNodeRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const currentCompanyIdRef = useRef<string | null>(null);

  // Initialize Audio Contexts
  const ensureAudioContext = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    if (audioContextRef.current.state === 'suspended') {
      audioContextRef.current.resume();
    }
  };

  // Helper: Base64 to ArrayBuffer
  const decodeAudioData = async (base64: string, ctx: AudioContext): Promise<AudioBuffer> => {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }

    // Convert PCM to AudioBuffer
    const dataInt16 = new Int16Array(bytes.buffer);
    const frameCount = dataInt16.length; 
    const buffer = ctx.createBuffer(1, frameCount, 24000); // 24kHz output from Gemini
    const channelData = buffer.getChannelData(0);

    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i] / 32768.0;
    }
    return buffer;
  };

  // Helper: Float32 to PCM Base64
  const createPcmData = (data: Float32Array) => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
      int16[i] = Math.max(-1, Math.min(1, data[i])) * 32768;
    }
    const bytes = new Uint8Array(int16.buffer);
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  };

  useEffect(() => {
    let mounted = true;

    const startSession = async () => {
      if (!isActive) return;

      try {
        setStatus('connecting');
        ensureAudioContext();

        // 1. Get API Key
        // In a real app, this should be securely handled. Assuming process.env is injected.
        const apiKey = (window as any).process?.env?.API_KEY || process.env.API_KEY; 
        if (!apiKey) throw new Error("No API Key");

        const ai = new GoogleGenAI({ apiKey });

        // 2. Setup Config & System Instruction
        const config = {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
          systemInstruction: `You are Recon's Voice Assistant. Keep responses concise, punchy, and professional. 
          You help the user analyze companies and strategize sales pitches.
          If the user is looking at a specific company, focus on that.`,
        };

        // 3. Connect Live Session
        sessionPromiseRef.current = ai.live.connect({
          model: 'gemini-2.5-flash-native-audio-preview-09-2025',
          config,
          callbacks: {
            onopen: async () => {
              if (!mounted) return;
              console.log("Recon Live: Connected");
              setStatus('listening');

              // Start Microphone
              mediaStreamRef.current = await navigator.mediaDevices.getUserMedia({ audio: true });

              if (!audioContextRef.current) return;

              const inputCtx = audioContextRef.current;
              sourceNodeRef.current = inputCtx.createMediaStreamSource(mediaStreamRef.current);
              processorRef.current = inputCtx.createScriptProcessor(4096, 1, 1);

              processorRef.current.onaudioprocess = (e) => {
                if (!mounted) return;
                const inputData = e.inputBuffer.getChannelData(0);

                // Visualization logic (simple volume meter)
                let sum = 0;
                for (let i = 0; i < inputData.length; i++) sum += inputData[i] * inputData[i];
                const rms = Math.sqrt(sum / inputData.length);
                setVolumeLevel(Math.min(1, rms * 5)); // Scale up for visual

                // Send to Gemini
                const pcmBase64 = createPcmData(inputData);
                sessionPromiseRef.current?.then(session => {
                  session.sendRealtimeInput({
                    media: {
                      mimeType: 'audio/pcm;rate=24000', // Browser default usually resampled, but we claim 24k for simplicity or match context
                      data: pcmBase64
                    }
                  });
                });
              };

              sourceNodeRef.current.connect(processorRef.current);
              processorRef.current.connect(inputCtx.destination);

              // Send Initial Context if Company exists
              if (contextCompany) {
                 const initialContext = `User is analyzing: ${contextCompany.name} (${contextCompany.industry}). 
                 Description: ${contextCompany.description.substring(0, 200)}...
                 Key Needs: ${contextCompany.needs.join(', ')}.`;

                 sessionPromiseRef.current?.then(session => {
                     session.sendRealtimeInput({ text: initialContext });
                 });
              }
            },
            onmessage: async (msg: LiveServerMessage) => {
              if (!mounted) return;

              const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
              if (audioData && audioContextRef.current) {
                setStatus('speaking');
                const buffer = await decodeAudioData(audioData, audioContextRef.current);

                const src = audioContextRef.current.createBufferSource();
                src.buffer = buffer;
                src.connect(audioContextRef.current.destination);

                const currentTime = audioContextRef.current.currentTime;
                // Schedule next chunk to avoid gaps
                const startTime = Math.max(currentTime, nextStartTimeRef.current);
                src.start(startTime);
                nextStartTimeRef.current = startTime + buffer.duration;

                src.onended = () => {
                    if (audioContextRef.current && audioContextRef.current.currentTime >= nextStartTimeRef.current) {
                        setStatus('listening');
                    }
                };
              }
            },
            onclose: () => {
              console.log("Recon Live: Closed");
              if (mounted) onClose();
            },
            onerror: (err) => {
              console.error("Recon Live Error:", err);
              if (mounted) setStatus('error');
            }
          }
        });

      } catch (err) {
        console.error("Setup Error", err);
        setStatus('error');
      }
    };

    if (isActive) {
      startSession();
    }

    return () => {
      mounted = false;
      // Cleanup
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(t => t.stop());
      }
      if (processorRef.current && sourceNodeRef.current) {
        processorRef.current.disconnect();
        sourceNodeRef.current.disconnect();
      }
      if (audioContextRef.current) {
        audioContextRef.current.close();
        audioContextRef.current = null;
      }
      // Note: No specific 'close' method on the session promise wrapper, relies on connection drop
      sessionPromiseRef.current = null;
    };
  }, [isActive]);

  // Handle Context Updates on the fly
  useEffect(() => {
    if (isActive && contextCompany && contextCompany.id !== currentCompanyIdRef.current && sessionPromiseRef.current) {
        currentCompanyIdRef.current = contextCompany.id;
        const updateMsg = `Context Update: User switched to ${contextCompany.name}. Focus on this company now.`;
        sessionPromiseRef.current.then(session => {
            session.sendRealtimeInput({ text: updateMsg });
        });
    }
  }, [contextCompany, isActive]);

  if (!isActive) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm animate-fade-in">
      <div className="relative w-full max-w-sm mx-auto p-6">

        {/* Main Card */}
        <div className="relative bg-neutral-900 border border-neutral-700 rounded-3xl shadow-2xl overflow-hidden flex flex-col items-center py-10">

            {/* Close Button */}
            <button 
                onClick={onClose}
                className="absolute top-4 right-4 p-2 rounded-full bg-neutral-800 text-neutral-400 hover:text-white transition-colors"
            >
                <X className="w-5 h-5" />
            </button>

            {/* Visualizer */}
            <div className="relative w-32 h-32 mb-8 flex items-center justify-center">
                {/* Outer Glow */}
                <div 
                    className={`absolute inset-0 rounded-full bg-accent/20 blur-xl transition-all duration-100 ease-linear`}
                    style={{ transform: `scale(${1 + volumeLevel})` }}
                ></div>

                {/* Core Orb */}
                <div 
                    className={`relative w-24 h-24 rounded-full flex items-center justify-center border-2 transition-all duration-300
                    ${status === 'error' ? 'border-red-500 bg-red-500/10' : 
                      status === 'speaking' ? 'border-accent bg-accent shadow-[0_0_30px_rgba(20,184,166,0.6)]' : 
                      'border-neutral-600 bg-neutral-800'}`}
                >
                    {status === 'connecting' && <Activity className="w-8 h-8 text-neutral-400 animate-pulse" />}
                    {status === 'listening' && <Mic className="w-8 h-8 text-white" />}
                    {status === 'speaking' && <Volume2 className="w-8 h-8 text-white animate-bounce" />}
                    {status === 'error' && <X className="w-8 h-8 text-red-500" />}
                </div>
            </div>

            {/* Status Text */}
            <h3 className="text-xl font-bold text-white mb-2">
                {status === 'connecting' && "Connecting..."}
                {status === 'listening' && "Listening"}
                {status === 'speaking' && "Recon AI"}
                {status === 'error' && "Connection Failed"}
            </h3>

            <p className="text-xs font-mono text-neutral-500 text-center max-w-[200px]">
                {status === 'error' ? "Please check microphone permissions." : 
                 contextCompany ? `Discussing ${contextCompany.name}` : "Ask me to find leads or analyze strategy."}
            </p>

            {/* Waveform Animation (Fake CSS for visuals) */}
            {status !== 'error' && (
                <div className="flex gap-1 mt-8 h-8 items-center">
                   {[...Array(5)].map((_, i) => (
                       <div 
                         key={i} 
                         className={`w-1 bg-accent rounded-full transition-all duration-150 ease-in-out`}
                         style={{ 
                             height: status === 'speaking' || (status === 'listening' && volumeLevel > 0.1) 
                               ? `${Math.random() * 24 + 8}px` 
                               : '4px',
                             opacity: 0.5 + Math.random() * 0.5
                         }}
                       ></div>
                   ))}
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

