                      noiseSuppression: true,
                      autoGainControl: true,
                      sampleRate: 16000 
                  }
              });

              if (!inputContextRef.current) return;

              const inputCtx = inputContextRef.current;
              sourceNodeRef.current = inputCtx.createMediaStreamSource(mediaStreamRef.current);
