import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Header } from './components/Header';
import { SearchPane } from './components/SearchPane';
import { IntelligencePane } from './components/IntelligencePane';
import { Sidebar } from './components/Sidebar';
import { VoiceMode } from './components/VoiceMode';
import { Company, SearchMode, SearchParams, Source } from './types';
import { findLeads } from './services/geminiService';
import { Menu, ChevronRight, X, Mic } from 'lucide-react';

// Simple Toast Component
const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className={`
        flex items-center gap-3 px-4 py-3 rounded-xl shadow-lg shadow-black/20 border backdrop-blur-md animate-fade-in-up
        ${type === 'error' ? 'bg-red-500/90 text-white border-red-500' : 
          type === 'success' ? 'bg-emerald-500/90 text-white border-emerald-500' : 
          'bg-neutral-800/90 text-white border-neutral-700'}
    `}>
      <span className="text-sm font-medium">{message}</span>
      <button onClick={onClose} className="opacity-70 hover:opacity-100 transition-opacity"><X size={14} /></button>
    </div>
  );
};

const App: React.FC = () => {
  // Initialize theme based on system preference
  const [isDarkMode, setIsDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
        return window.matchMedia('(prefers-color-scheme: dark)').matches;
    }
    return true;
  });

  const [toasts, setToasts] = useState<{ id: number; message: string; type: 'success' | 'error' | 'info' }[]>([]);

  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);

  // Voice Mode State
  const [isVoiceModeActive, setIsVoiceModeActive] = useState(false);

  // State for Live Results vs Saved Targets
  const [searchResults, setSearchResults] = useState<Company[]>([]);
  const [searchSources, setSearchSources] = useState<Source[]>([]);

  const [savedCompanies, setSavedCompanies] = useState<Company[]>(() => {
    // Basic persistence
    const saved = localStorage.getItem('recon_saved_targets');
    return saved ? JSON.parse(saved) : [];
  });

  // Pre-fetching State
  const [nextBatch, setNextBatch] = useState<{ leads: Company[], sources: Source[] } | null>(null);
  const [isPrefetching, setIsPrefetching] = useState(false);

  const [isSearching, setIsSearching] = useState(false);
  const [showMobileSidebar, setShowMobileSidebar] = useState(false);

  const currentSearchParamsRef = useRef<SearchParams | null>(null);

  // Abort Controller Ref to handle cancellation
  const abortControllerRef = useRef<AbortController | null>(null);

  const addToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now(), message, type }]);
  };

  const removeToast = (id: number) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  // Initialize theme
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      document.documentElement.classList.remove('light');
    } else {
      document.documentElement.classList.remove('dark');
      document.documentElement.classList.add('light');
    }
  }, [isDarkMode]);

  // Persist Saved Companies
  useEffect(() => {
    localStorage.setItem('recon_saved_targets', JSON.stringify(savedCompanies));
  }, [savedCompanies]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  // Mouse tracking
  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    const x = e.clientX;
    const y = e.clientY;
    document.documentElement.style.setProperty('--mouse-x', `${x}px`);
    document.documentElement.style.setProperty('--mouse-y', `${y}px`);
  }, []);

  // BACKGROUND TASK: Prefetch the next 5 leads
  const prefetchNextBatch = async (currentResults: Company[], params: SearchParams) => {
    if (params.mode === 'lookup') return; // Don't prefetch for single lookups

    setIsPrefetching(true);
    try {
        const excludeNames = [...currentResults.map(c => c.name), ...savedCompanies.map(c => c.name)];
        const nextParams = { ...params, excludeNames };

        const result = await findLeads(nextParams, abortControllerRef.current?.signal);
        setNextBatch(result);
    } catch (error: any) {
        if (error.name !== 'AbortError') {
            console.log("Prefetch suspended or failed (non-critical).");
        }
    } finally {
        setIsPrefetching(false);
    }
  };

  const handleSearch = async (mode: SearchMode, p1: string, p2: string) => {
    // 1. STOP EVERYTHING
    if (abortControllerRef.current) {
        abortControllerRef.current.abort();
    }
    abortControllerRef.current = new AbortController();

    setIsSearching(true);
    setSearchResults([]); 
    setSearchSources([]);
    setNextBatch(null); 
    setSelectedCompanyId(null);

    const params: SearchParams = {
        mode,
        industry: mode === 'discovery' ? p1 : undefined,
        city: p2,
        companyName: mode === 'lookup' ? p1 : undefined,
        excludeNames: savedCompanies.map(c => c.name)
    };
    currentSearchParamsRef.current = params;

    try {
      const { leads, sources } = await findLeads(params, abortControllerRef.current.signal);
      setSearchResults(leads);
      setSearchSources(sources);

      if (leads.length === 0) {
        addToast("No leads found. Try a broader search.", "info");
      } else {
        prefetchNextBatch(leads, params);
      }
    } catch (error: any) {
      if (error.name === 'AbortError') {
          console.log("Search aborted by user.");
      } else {
          console.error("Search failed", error);
          addToast(error.message || "Could not find leads.", "error");
      }
    } finally {
      if (!abortControllerRef.current?.signal.aborted) {
          setIsSearching(false);
      }
    }
  };

  const handleLoadMore = async () => {
    if (!currentSearchParamsRef.current || currentSearchParamsRef.current.mode === 'lookup') return;

    // STRATEGY: Instant Load if buffer is ready
    if (nextBatch && nextBatch.leads.length > 0) {
        const batchLeads = nextBatch.leads;
        const batchSources = nextBatch.sources;

        setNextBatch(null); // Clear buffer immediately

        setSearchResults(prev => {
            const updated = [...prev, ...batchLeads];
            prefetchNextBatch(updated, currentSearchParamsRef.current!); 
            return updated;
        });
        setSearchSources(prev => {
            // Merge and dedupe sources
            const combined = [...prev, ...batchSources];
            return combined.filter((v, i, a) => a.findIndex(t => (t.uri === v.uri)) === i);
        });
        return;
    }

    // Fallback
    setIsSearching(true);
    try {
      const excludeNames = [...searchResults.map(c => c.name), ...savedCompanies.map(c => c.name)];
      const params: SearchParams = { ...currentSearchParamsRef.current, excludeNames };

      const { leads, sources } = await findLeads(params, abortControllerRef.current?.signal);

      if (leads.length === 0) {
        addToast("No more unique leads found in this area.", "info");
      } else {
        setSearchResults(prev => {
            const updated = [...prev, ...leads];
            prefetchNextBatch(updated, currentSearchParamsRef.current!);
            return updated;
        });
        setSearchSources(prev => {
             const combined = [...prev, ...sources];
             return combined.filter((v, i, a) => a.findIndex(t => (t.uri === v.uri)) === i);
        });
      }
    } catch (error: any) {
       if (error.name !== 'AbortError') {
          addToast(error.message || "Failed to load more leads.", "error");
       }
    } finally {
      setIsSearching(false);
    }
  };

  const toggleSaveCompany = (company: Company) => {
    if (savedCompanies.some(c => c.id === company.id)) {
        // Remove
        setSavedCompanies(prev => prev.filter(c => c.id !== company.id));
        addToast("Company removed from saved list", "info");
    } else {
        // Add
        const newCompany = { ...company, status: 'Saved' as const };
        setSavedCompanies(prev => [newCompany, ...prev]);
        addToast("Company saved successfully", "success");
    }
  };

  const removeMultipleSavedCompanies = (ids: string[]) => {
    setSavedCompanies(prev => prev.filter(c => !ids.includes(c.id)));
    if (selectedCompanyId && ids.includes(selectedCompanyId)) {
        setSelectedCompanyId(null);
    }
    addToast(`Deleted ${ids.length} companies`, "info");
  };

  const selectedCompany = 
    searchResults.find(c => c.id === selectedCompanyId) || 
    savedCompanies.find(c => c.id === selectedCompanyId) || 
    null;

  return (
    <div 
      onMouseMove={handleMouseMove}
      className="h-screen bg-neutral-50 dark:bg-neutral-950 transition-colors duration-400 overflow-hidden flex flex-col relative"
    >
      {/* Voice Mode Overlay */}
      <VoiceMode 
        isActive={isVoiceModeActive} 
        onClose={() => setIsVoiceModeActive(false)} 
        contextCompany={selectedCompany} 
      />

      {/* Floating Action Button for Voice - High Z-Index to Ensure Visibility */}
      <div className="fixed bottom-6 right-6 z-[100] flex flex-col items-end space-y-4 pointer-events-none">
         {/* Toast Area */}
         <div className="flex flex-col gap-2 pointer-events-auto items-end">
            {toasts.map(toast => (
                <Toast key={toast.id} {...toast} onClose={() => removeToast(toast.id)} />
            ))}
         </div>

         {/* FAB */}
         <button
            onClick={() => setIsVoiceModeActive(true)}
            className="pointer-events-auto group relative flex items-center justify-center w-14 h-14 rounded-full bg-gradient-to-tr from-accent to-accent-glow text-white shadow-lg shadow-accent/40 hover:scale-110 hover:shadow-accent/60 transition-all duration-300 ease-out"
            aria-label="Start Voice Assistant"
         >
            <div className="absolute inset-0 rounded-full bg-white opacity-0 group-hover:opacity-20 animate-ping duration-1000"></div>
            <div className="absolute inset-0 rounded-full bg-gradient-to-tr from-accent to-accent-glow opacity-80 blur-md"></div>
            <Mic className="w-6 h-6 relative z-10 drop-shadow-sm" />
         </button>
      </div>

      <div className="fixed inset-0 pointer-events-none overflow-hidden z-0">
        <div className={`absolute -top-[20%] -left-[10%] w-[50%] h-[50%] rounded-full blur-[120px] transition-opacity duration-1000 ${isDarkMode ? 'bg-accent/5' : 'bg-accent/10'}`}></div>
        <div className="absolute inset-0 spotlight-bg opacity-100 transition-opacity duration-500"></div>
      </div>

      <div className="relative z-10 flex flex-col h-full">
        <Header 
            isDarkMode={isDarkMode} 
            toggleTheme={toggleTheme} 
            onVoiceToggle={() => setIsVoiceModeActive(true)}
        />

        <main className="flex-1 w-full max-w-screen-2xl mx-auto flex overflow-hidden">

          <div className="hidden lg:block w-72 h-full shrink-0">
             <Sidebar 
                savedCompanies={savedCompanies}
                onSelectCompany={(c) => setSelectedCompanyId(c.id)}
                selectedCompanyId={selectedCompanyId}
                onRemoveCompanies={removeMultipleSavedCompanies}
             />
          </div>

           {showMobileSidebar && (
              <div className="fixed inset-0 z-50 lg:hidden flex">
                  <div className="w-72 h-full bg-neutral-900 shadow-2xl animate-fade-in">
                     <Sidebar 
                        savedCompanies={savedCompanies}
                        onSelectCompany={(c) => { setSelectedCompanyId(c.id); setShowMobileSidebar(false); }}
                        selectedCompanyId={selectedCompanyId}
                        onRemoveCompanies={removeMultipleSavedCompanies}
                     />
                  </div>
                  <div className="flex-1 bg-black/50 backdrop-blur-sm" onClick={() => setShowMobileSidebar(false)}></div>
              </div>
           )}

          <div className="flex-1 flex flex-col lg:flex-row min-w-0">

            <div className="lg:hidden p-2 border-b border-neutral-200 dark:border-white/10 flex items-center justify-between bg-neutral-100/50 dark:bg-neutral-900/50">
               <button onClick={() => setShowMobileSidebar(true)} className="flex items-center gap-2 text-xs font-bold uppercase text-neutral-500">
                  <Menu className="w-4 h-4" /> Open Saved List
               </button>
               <span className="text-[10px] text-accent font-mono">{savedCompanies.length} SAVED</span>
            </div>

            <div className={`
                flex-1 flex flex-col h-full min-w-0 border-r border-neutral-200 dark:border-white/5 bg-white/30 dark:bg-neutral-950/30
                ${selectedCompanyId ? 'hidden lg:flex' : 'flex'} 
            `}>
              <div className="p-4 h-full">
                <SearchPane 
                    companies={searchResults} 
                    sources={searchSources}
                    selectedCompanyId={selectedCompanyId}
                    onSelectCompany={setSelectedCompanyId}
                    onSearch={handleSearch}
                    onLoadMore={handleLoadMore}
                    isSearching={isSearching}
                />
              </div>
            </div>

            <div className={`
                lg:w-[600px] xl:w-[700px] h-full flex-col bg-white/50 dark:bg-neutral-900/50 backdrop-blur-md
                ${selectedCompanyId ? 'flex fixed inset-0 z-40 lg:static lg:z-auto' : 'hidden lg:flex'}
            `}>
               {selectedCompanyId && (
                  <div className="lg:hidden p-4 border-b border-neutral-200 dark:border-white/10 flex items-center justify-between bg-white dark:bg-neutral-900">
                      <button 
                          onClick={() => setSelectedCompanyId(null)}
                          className="text-sm font-medium text-neutral-500 flex items-center gap-2"
                      >
                          <ChevronRight className="w-4 h-4 rotate-180" /> Back
                      </button>
                  </div>
               )}

               <div className="flex-1 h-full overflow-hidden p-4">
                  <IntelligencePane 
                      company={selectedCompany} 
                      onToggleSave={() => selectedCompany && toggleSaveCompany(selectedCompany)}
                      isSaved={!!selectedCompany && savedCompanies.some(c => c.id === selectedCompany.id)}
                  />
               </div>
            </div>

          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import { Mic, X, Activity, Volume2, Globe, Wifi } from 'lucide-react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { Company } from '../types';

interface VoiceModeProps {
  isActive: boolean;
  onClose: () => void;
  contextCompany: Company | null;
}

export const VoiceMode: React.FC<VoiceModeProps> = ({ isActive, onClose, contextCompany }) => {
  const [status, setStatus] = useState<'connecting' | 'listening' | 'speaking' | 'error'>('connecting');
  const [volumeLevel, setVolumeLevel] = useState(0);

  // Refs for Audio Handling
  const inputContextRef = useRef<AudioContext | null>(null);
  const outputContextRef = useRef<AudioContext | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);
  const sourceNodeRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const currentCompanyIdRef = useRef<string | null>(null);
  const audioSourcesRef = useRef<AudioBufferSourceNode[]>([]);

  // Initialize Audio Contexts
  // We use 16kHz for input (Gemini requirement) and 24kHz for output (Gemini high-quality voice)
  const ensureAudioContexts = () => {
    if (!inputContextRef.current) {
      inputContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
    }
    if (!outputContextRef.current) {
      outputContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }

    // Resume if suspended (browser autoplay policy)
    if (inputContextRef.current.state === 'suspended') inputContextRef.current.resume();
    if (outputContextRef.current.state === 'suspended') outputContextRef.current.resume();
  };

  const stopAllAudio = () => {
    audioSourcesRef.current.forEach(source => {
      try { source.stop(); } catch (e) { /* ignore */ }
      try { source.disconnect(); } catch (e) { /* ignore */ }
    });
    audioSourcesRef.current = [];
    if (outputContextRef.current) {
        nextStartTimeRef.current = outputContextRef.current.currentTime;
    }
  };

  // Helper: Base64 to ArrayBuffer
  const decodeAudioData = async (base64: string, ctx: AudioContext): Promise<AudioBuffer> => {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }

    // Convert PCM to AudioBuffer
    const dataInt16 = new Int16Array(bytes.buffer);
    const frameCount = dataInt16.length; 
    const buffer = ctx.createBuffer(1, frameCount, 24000); // 24kHz output from Gemini
    const channelData = buffer.getChannelData(0);

    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i] / 32768.0;
    }
    return buffer;
  };

  // Helper: Float32 to PCM Base64 (16-bit)
  const createPcmData = (data: Float32Array) => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
      int16[i] = Math.max(-1, Math.min(1, data[i])) * 32768;
    }
    const bytes = new Uint8Array(int16.buffer);
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  };

  useEffect(() => {
    let mounted = true;

    const startSession = async () => {
      if (!isActive) return;

      try {
        setStatus('connecting');
        ensureAudioContexts();

        const apiKey = (window as any).process?.env?.API_KEY || process.env.API_KEY; 
        if (!apiKey) throw new Error("No API Key");

        const ai = new GoogleGenAI({ apiKey });

        const config = {
          responseModalities: [Modality.AUDIO],
          tools: [{ googleSearch: {} }], // Enable Search for real-time intelligence
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
          systemInstruction: `You are Recon's Voice Assistant. Keep responses concise, punchy, and professional. 
          You help the user analyze companies and strategize sales pitches.
          If the user is looking at a specific company, focus on that.
          Do not be verbose. Be helpful and direct.
          Use Google Search to answer questions about recent news or company details.`,
        };

        sessionPromiseRef.current = ai.live.connect({
          model: 'gemini-2.5-flash-native-audio-preview-09-2025',
          config,
          callbacks: {
            onopen: async () => {
              if (!mounted) return;
              console.log("Recon Live: Connected");
              setStatus('listening');

              // Start Microphone with Echo Cancellation
              mediaStreamRef.current = await navigator.mediaDevices.getUserMedia({ 
                  audio: {
                      echoCancellation: true,
                      noiseSuppression: true,
                      autoGainControl: true,
                      sampleRate: 16000 
                  }
              });

              if (!inputContextRef.current) return;

              const inputCtx = inputContextRef.current;
              sourceNodeRef.current = inputCtx.createMediaStreamSource(mediaStreamRef.current);
              // Reduced buffer size to 2048 for lower latency (approx 128ms)
              processorRef.current = inputCtx.createScriptProcessor(2048, 1, 1);

              processorRef.current.onaudioprocess = (e) => {
                if (!mounted) return;
                const inputData = e.inputBuffer.getChannelData(0);

                // Visualization
                let sum = 0;
                for (let i = 0; i < inputData.length; i++) sum += inputData[i] * inputData[i];
                const rms = Math.sqrt(sum / inputData.length);
                setVolumeLevel(Math.min(1, rms * 5)); 

                // Send to Gemini
                const pcmBase64 = createPcmData(inputData);
                sessionPromiseRef.current?.then(session => {
                  session.sendRealtimeInput({
                    media: {
                      mimeType: 'audio/pcm;rate=16000', // Explicitly 16kHz
                      data: pcmBase64
                    }
                  });
                });
              };

              sourceNodeRef.current.connect(processorRef.current);
              processorRef.current.connect(inputCtx.destination);

              if (contextCompany) {
                 const initialContext = `User is analyzing: ${contextCompany.name} (${contextCompany.industry}). 
                 Description: ${contextCompany.description.substring(0, 200)}...
                 Key Needs: ${contextCompany.needs.join(', ')}.`;

                 sessionPromiseRef.current?.then(session => {
                     session.sendRealtimeInput({ text: initialContext });
                 });
              }
            },
            onmessage: async (msg: LiveServerMessage) => {
              if (!mounted) return;

              // Handle Interruption
              if (msg.serverContent?.interrupted) {
                  console.log("Recon Live: Interrupted");
                  stopAllAudio();
                  setStatus('listening');
                  return;
              }

              // Handle Audio Output
              const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
              if (audioData && outputContextRef.current) {
                setStatus('speaking');
                const buffer = await decodeAudioData(audioData, outputContextRef.current);

                const src = outputContextRef.current.createBufferSource();
                src.buffer = buffer;
                src.connect(outputContextRef.current.destination);

                // Track source for cancellation
                audioSourcesRef.current.push(src);
                src.onended = () => {
                    audioSourcesRef.current = audioSourcesRef.current.filter(s => s !== src);
                    if (audioSourcesRef.current.length === 0 && mounted) {
                        setStatus('listening');
                    }
                };

                const currentTime = outputContextRef.current.currentTime;
                const startTime = Math.max(currentTime, nextStartTimeRef.current);
                src.start(startTime);
                nextStartTimeRef.current = startTime + buffer.duration;
              }
            },
            onclose: () => {
              console.log("Recon Live: Closed");
              if (mounted) onClose();
            },
            onerror: (err) => {
              console.error("Recon Live Error:", err);
              if (mounted) setStatus('error');
            }
          }
        });

      } catch (err) {
        console.error("Setup Error", err);
        setStatus('error');
      }
    };

    if (isActive) {
      startSession();
    }

    return () => {
      mounted = false;
      stopAllAudio();

      // Cleanup Input
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(t => t.stop());
      }
      if (processorRef.current && sourceNodeRef.current) {
        processorRef.current.disconnect();
        sourceNodeRef.current.disconnect();
      }
      if (inputContextRef.current) {
        inputContextRef.current.close();
        inputContextRef.current = null;
      }
      // Cleanup Output
      if (outputContextRef.current) {
        outputContextRef.current.close();
        outputContextRef.current = null;
      }
      sessionPromiseRef.current = null;
    };
  }, [isActive]);

  // Handle Context Updates
  useEffect(() => {
    if (isActive && contextCompany && contextCompany.id !== currentCompanyIdRef.current && sessionPromiseRef.current) {
        currentCompanyIdRef.current = contextCompany.id;
        const updateMsg = `Context Update: User switched to ${contextCompany.name}. Focus on this company now.`;
        sessionPromiseRef.current.then(session => {
            session.sendRealtimeInput({ text: updateMsg });
        });
    }
  }, [contextCompany, isActive]);

  if (!isActive) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm animate-fade-in">
      <div className="relative w-full max-w-sm mx-auto p-6">

        {/* Main Card */}
        <div className="relative bg-neutral-900 border border-neutral-700 rounded-3xl shadow-2xl overflow-hidden flex flex-col items-center py-10 transition-all duration-300">

            {/* Close Button */}
            <button 
                onClick={onClose}
                className="absolute top-4 right-4 p-2 rounded-full bg-neutral-800 text-neutral-400 hover:text-white transition-colors hover:rotate-90 duration-300"
            >
                <X className="w-5 h-5" />
            </button>

            {/* Connection Status Indicator */}
            <div className="absolute top-5 left-6 flex items-center gap-2">
                 <div className={`w-2 h-2 rounded-full ${status === 'error' ? 'bg-red-500' : (status === 'connecting' ? 'bg-amber-500 animate-pulse' : 'bg-emerald-500')}`}></div>
                 <span className="text-[10px] font-mono text-neutral-500 uppercase">
                    {status === 'connecting' ? 'SYNCING' : 'LIVE'}
                 </span>
            </div>

            {/* Visualizer Orb */}
            <div className="relative w-40 h-40 mb-8 flex items-center justify-center">
                {/* Background Rotating Ring 1 */}
                <div 
                    className="absolute inset-0 rounded-full border-2 border-accent/20 border-t-accent/60 animate-[spin_3s_linear_infinite]"
                    style={{ transform: `scale(${1 + volumeLevel * 0.5})` }}
                ></div>

                {/* Background Rotating Ring 2 (Counter-rotate) */}
                <div 
                    className="absolute inset-4 rounded-full border-2 border-purple-500/20 border-b-purple-500/60 animate-[spin_4s_linear_infinite_reverse]"
                    style={{ transform: `scale(${1 + volumeLevel * 0.3})` }}
                ></div>

                {/* Core Glow */}
                <div 
                    className={`absolute inset-0 rounded-full bg-accent/20 blur-2xl transition-all duration-100 ease-linear`}
                    style={{ transform: `scale(${1 + volumeLevel * 1.5})`, opacity: volumeLevel + 0.5 }}
                ></div>

                {/* Center Core */}
                <div 
                    className={`relative w-24 h-24 rounded-full flex items-center justify-center border transition-all duration-300 shadow-lg z-10
                    ${status === 'error' ? 'border-red-500 bg-red-900/50 shadow-red-500/50' : 
                      status === 'speaking' ? 'border-accent bg-accent text-white shadow-accent/50 scale-110' : 
                      'border-neutral-700 bg-neutral-800 text-neutral-400'}`}
                >
                    {status === 'connecting' && <Activity className="w-8 h-8 animate-pulse" />}
                    {status === 'listening' && <div className={`w-3 h-3 rounded-full bg-red-500 animate-pulse transition-all ${volumeLevel > 0.1 ? 'scale-150' : ''}`} />}
                    {status === 'speaking' && <Volume2 className="w-8 h-8 animate-bounce" />}
                    {status === 'error' && <X className="w-8 h-8" />}
                </div>
            </div>

            {/* Status Text */}
            <h3 className="text-xl font-bold text-white mb-2 tracking-wide uppercase">
                {status === 'connecting' && "Connecting..."}
                {status === 'listening' && "Listening"}
                {status === 'speaking' && "Recon AI"}
                {status === 'error' && "Connection Error"}
            </h3>

            <p className="text-xs font-mono text-neutral-500 text-center max-w-[240px] leading-relaxed">
                {status === 'error' ? "Microphone access denied or connection dropped." : 
                 contextCompany ? `Analyzing ${contextCompany.name}. Ask for recent news or strategy.` : "I'm listening. Ask me to find leads or research companies."}
            </p>

            {/* Dynamic Waveform */}
            {status !== 'error' && (
                <div className="flex gap-1.5 mt-8 h-12 items-center justify-center">
                   {[...Array(7)].map((_, i) => (
                       <div 
                         key={i} 
                         className={`w-1.5 rounded-full transition-all duration-150 ease-in-out ${status === 'speaking' ? 'bg-accent' : 'bg-neutral-700'}`}
                         style={{ 
                             height: status === 'speaking' || (status === 'listening' && volumeLevel > 0.05) 
                               ? `${Math.random() * 40 + 10}px` 
                               : '4px',
                             opacity: status === 'speaking' ? 0.8 : 0.5
                         }}
                       ></div>
                   ))}
                </div>
            )}

            {/* Tool Indicators (Static for now, but implies capability) */}
            <div className="absolute bottom-4 flex gap-3 text-neutral-600">
               <Globe className="w-4 h-4 opacity-50" />
               <Wifi className="w-4 h-4 opacity-50" />
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Search, MapPin, Briefcase, ChevronRight, Globe, Loader2, Radar, Building2, Flame, ExternalLink, RefreshCw } from 'lucide-react';
import { Company, SearchMode, Source } from '../types';

interface SearchPaneProps {
  companies: Company[];
  sources?: Source[];
  selectedCompanyId: string | null;
  onSelectCompany: (id: string) => void;
  onSearch?: (mode: SearchMode, p1: string, p2: string) => void;
  onLoadMore?: () => void;
  isSearching?: boolean;
}

export const SearchPane: React.FC<SearchPaneProps> = ({ 
  companies,
  sources = [],
  selectedCompanyId, 
  onSelectCompany,
  onSearch,
  onLoadMore,
  isSearching = false
}) => {
  const [mode, setMode] = useState<SearchMode>('discovery');

  // Discovery Inputs
  const [industry, setIndustry] = useState('');
  const [city, setCity] = useState('');

  // Lookup Inputs
  const [companyName, setCompanyName] = useState('');
  const [lookupCity, setLookupCity] = useState('');

  // Loading Message State
  const [loadingText, setLoadingText] = useState('Searching...');

  // Infinite Scroll Ref
  const loadMoreRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isSearching) return;

    const messages = [
        "Analyzing Industry...",
        "Finding Companies...",
        "Finding Contact Info...",
        "Verifying Details...",
        "Preparing Report..."
    ];

    let i = 0;
    const interval = setInterval(() => {
        setLoadingText(messages[i]);
        i = (i + 1) % messages.length;
    }, 1200);

    return () => clearInterval(interval);
  }, [isSearching]);

  // Infinite Scroll Observer
  useEffect(() => {
    if (!onLoadMore || mode !== 'discovery' || isSearching || companies.length === 0) return;

    const observer = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) {
        onLoadMore();
      }
    }, { threshold: 0.1 });

    if (loadMoreRef.current) {
      observer.observe(loadMoreRef.current);
    }

    return () => observer.disconnect();
  }, [companies.length, isSearching, mode, onLoadMore]);

  const handleSubmit = () => {
    if (!onSearch) return;

    if (mode === 'discovery') {
       if (industry && city) onSearch('discovery', industry, city);
    } else {
       if (companyName) onSearch('lookup', companyName, lookupCity || 'Anywhere'); 
    }
  };

  const getHotScoreColor = (score: number) => {
    if (score >= 80) return 'from-red-500 to-orange-500';
    if (score >= 60) return 'from-orange-400 to-amber-400';
    return 'from-neutral-400 to-neutral-500';
  };

  return (
    <div className="flex flex-col h-full">

      {/* Search Header Area - Fixed Top */}
      <div className="mb-2 space-y-4 relative z-10 bg-neutral-50 dark:bg-neutral-950 pb-2">
        <div className="flex items-center justify-between px-1">
             <h2 className="text-lg font-semibold text-neutral-900 dark:text-white tracking-tight">
               Search & Leads
             </h2>
             {/* Mode Toggles */}
             <div className="flex p-1 rounded-lg bg-neutral-200 dark:bg-white/5 border border-neutral-200 dark:border-white/5">
                 <button
                    onClick={() => setMode('discovery')}
                    className={`px-3 py-1 text-[10px] font-bold uppercase tracking-wider rounded-md transition-all ${mode === 'discovery' ? 'bg-white dark:bg-neutral-800 text-accent shadow-sm' : 'text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}
                 >
                    Discover
                 </button>
                 <button
                    onClick={() => setMode('lookup')}
                    className={`px-3 py-1 text-[10px] font-bold uppercase tracking-wider rounded-md transition-all ${mode === 'lookup' ? 'bg-white dark:bg-neutral-800 text-accent shadow-sm' : 'text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}
                 >
                    Lookup
                 </button>
             </div>
        </div>

        <div className="space-y-3">
          {mode === 'discovery' ? (
              <>
                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Briefcase className="h-4 w-4 text-neutral-400 group-focus-within:text-accent transition-colors duration-300" />
                    </div>
                    <input
                    type="text"
                    value={industry}
                    onChange={(e) => setIndustry(e.target.value)}
                    placeholder="Industry (e.g. Fintech)"
                    onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
                    className="block w-full pl-10 pr-3 py-3 rounded-xl border border-neutral-200 dark:border-white/10 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-white placeholder-neutral-400 focus:outline-none focus:ring-2 focus:ring-accent focus:border-transparent transition-all shadow-sm hover:shadow-md dark:hover:bg-neutral-800"
                    />
                </div>

                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <MapPin className="h-4 w-4 text-neutral-400 group-focus-within:text-accent transition-colors duration-300" />
                    </div>
                    <input
                    type="text"
                    value={city}
                    onChange={(e) => setCity(e.target.value)}
                    placeholder="City (e.g. London)"
                    onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
                    className="block w-full pl-10 pr-3 py-3 rounded-xl border border-neutral-200 dark:border-white/10 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-white placeholder-neutral-400 focus:outline-none focus:ring-2 focus:ring-accent focus:border-transparent transition-all shadow-sm hover:shadow-md dark:hover:bg-neutral-800"
                    />
                </div>
              </>
          ) : (
              <>
                 <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Building2 className="h-4 w-4 text-neutral-400 group-focus-within:text-accent transition-colors duration-300" />
                    </div>
                    <input
                    type="text"
                    value={companyName}
                    onChange={(e) => setCompanyName(e.target.value)}
                    placeholder="Company Name"
                    onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
                    className="block w-full pl-10 pr-3 py-3 rounded-xl border border-neutral-200 dark:border-white/10 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-white placeholder-neutral-400 focus:outline-none focus:ring-2 focus:ring-accent focus:border-transparent transition-all shadow-sm hover:shadow-md dark:hover:bg-neutral-800"
                    />
                </div>

                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <MapPin className="h-4 w-4 text-neutral-400 group-focus-within:text-accent transition-colors duration-300" />
                    </div>
                    <input
                    type="text"
                    value={lookupCity}
                    onChange={(e) => setLookupCity(e.target.value)}
                    placeholder="City (Optional)"
                    onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
                    className="block w-full pl-10 pr-3 py-3 rounded-xl border border-neutral-200 dark:border-white/10 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-white placeholder-neutral-400 focus:outline-none focus:ring-2 focus:ring-accent focus:border-transparent transition-all shadow-sm hover:shadow-md dark:hover:bg-neutral-800"
                    />
                </div>
              </>
          )}

          <button 
            onClick={handleSubmit}
            disabled={isSearching || (mode === 'discovery' ? (!industry || !city) : !companyName)}
            className={`
              w-full flex items-center justify-center py-3 px-4 rounded-xl font-medium transition-all duration-300 shadow-lg 
              ${isSearching || (mode === 'discovery' ? (!industry || !city) : !companyName)
                ? 'bg-neutral-200 dark:bg-neutral-800 text-neutral-400 cursor-not-allowed shadow-none' 
                : 'bg-accent hover:bg-accent-glow text-white shadow-accent/20 hover:shadow-accent/40 active:scale-[0.98]'}
            `}
          >
            {isSearching && companies.length === 0 ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Search className="w-4 h-4 mr-2" />}
            {isSearching && companies.length === 0 ? (
                <span className="font-mono text-xs uppercase tracking-wide animate-pulse">{loadingText}</span>
            ) : (
                mode === 'discovery' ? 'Find Leads' : 'Search Company'
            )}
          </button>
        </div>
      </div>

      {/* Soft Gradient Divider */}
      <div className="h-6 w-full bg-gradient-to-b from-neutral-50 via-neutral-50 to-transparent dark:from-neutral-950 dark:via-neutral-950 z-10 shrink-0"></div>

      {/* Results List - SCROLLABLE AREA */}
      <div id="results-container" className="flex-1 overflow-y-auto -mx-2 px-2 pb-4 space-y-3 min-h-0 custom-scrollbar">
        {companies.length === 0 && !isSearching && (
          <div className="h-full flex flex-col items-center justify-center text-center opacity-60 animate-fade-in p-8">
             <div className="w-16 h-16 rounded-full bg-neutral-100 dark:bg-neutral-900/50 flex items-center justify-center mb-4 ring-1 ring-neutral-200 dark:ring-white/5">
                 <Radar className="w-8 h-8 text-neutral-400" />
             </div>
             <h3 className="text-sm font-semibold text-neutral-900 dark:text-white mb-1">
               Ready to Search
             </h3>
             <p className="text-xs text-neutral-500 max-w-[200px] leading-relaxed">
               {mode === 'discovery' ? "Enter an Industry and City above to find leads." : "Enter a Company Name to find contact details."}
             </p>
          </div>
        )}

        {companies.map((company, index) => {
          const isSelected = selectedCompanyId === company.id;
          const animationDelay = `${(index % 10) * 50}ms`;
          const hotColor = getHotScoreColor(company.hotScore);

          return (
            <div
              key={company.id}
              onClick={() => onSelectCompany(company.id)}
              style={{ animationDelay }}
              className={`
                relative p-4 rounded-xl border cursor-pointer transition-all duration-300 group opacity-0 animate-fade-in-up
                ${isSelected 
                  ? 'bg-white dark:bg-neutral-800 border-accent shadow-md ring-1 ring-accent z-10 scale-[1.01]' 
                  : 'bg-white dark:bg-neutral-900/50 border-neutral-200 dark:border-white/5 hover:border-neutral-300 dark:hover:border-white/20 hover:shadow-sm hover:bg-white dark:hover:bg-neutral-800/80'}
              `}
            >
              <div className="flex justify-between items-start">
                <div className="flex-1 mr-2">
                  <h3 className={`font-semibold text-sm transition-colors ${isSelected ? 'text-neutral-900 dark:text-white' : 'text-neutral-700 dark:text-neutral-200 group-hover:text-neutral-900 dark:group-hover:text-white'}`}>
                    {company.name}
                  </h3>
                  <div className="flex items-center mt-1 space-x-2">
                      {company.website !== 'N/A' && (
                        <>
                          <Globe className="w-3 h-3 text-neutral-400 group-hover:text-accent transition-colors" />
                          <a 
                             href={company.website.startsWith('http') ? company.website : `https://${company.website}`} 
                             target="_blank" 
                             rel="noreferrer"
                             onClick={(e) => e.stopPropagation()} 
                             className="text-xs text-neutral-500 hover:text-accent hover:underline truncate max-w-[150px] transition-colors"
                          >
                            {company.website.replace(/^https?:\/\/(www\.)?/, '')}
                          </a>
                        </>
                      )}
                  </div>
                </div>

                {/* Hot Score Badge */}
                <div className={`
                    flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold text-white shadow-sm
                    bg-gradient-to-r ${hotColor}
                `}>
                    <Flame className="w-3 h-3 fill-white/90" />
                    <span>{company.hotScore}%</span>
                </div>
              </div>

              {/* Active Indicator Slide-in */}
              <div className={`
                  mt-3 flex items-center text-xs font-medium text-accent overflow-hidden transition-all duration-300 ease-out
                  ${isSelected ? 'max-h-6 opacity-100 translate-y-0' : 'max-h-0 opacity-0 -translate-y-2'}
              `}>
                  <span>Selected</span>
                  <ChevronRight className="w-3 h-3 ml-1" />
              </div>
            </div>
          );
        })}

        {/* Infinite Scroll Trigger Area */}
        {companies.length > 0 && mode === 'discovery' && (
           <div ref={loadMoreRef} className="py-4 flex flex-col items-center justify-center opacity-70">
              {isSearching ? (
                 <div className="flex items-center gap-2 text-xs text-neutral-500">
                    <Loader2 className="w-4 h-4 animate-spin text-accent" />
                    <span className="animate-pulse">Loading more leads...</span>
                 </div>
              ) : (
                 <div className="h-4"></div> // Spacer trigger
              )}
           </div>
        )}

        {/* Verified Sources Footer */}
        {sources.length > 0 && (
          <div className="mt-6 pt-4 border-t border-neutral-200 dark:border-white/10 opacity-70 hover:opacity-100 transition-opacity">
            <h4 className="text-[10px] font-bold uppercase text-neutral-500 mb-2">Verified Sources</h4>
            <div className="flex flex-wrap gap-2">
              {sources.map((source, idx) => (
                <a 
                  key={idx}
                  href={source.uri}
                  target="_blank"
                  rel="noreferrer"
                  className="flex items-center gap-1 px-2 py-1 rounded bg-neutral-100 dark:bg-white/5 border border-neutral-200 dark:border-white/10 text-[10px] text-neutral-600 dark:text-neutral-400 hover:text-accent hover:border-accent/30 transition-colors truncate max-w-full"
                  title={source.title}
                >
                  <ExternalLink className="w-3 h-3" />
                  <span className="truncate max-w-[150px]">{source.title || new URL(source.uri).hostname}</span>
                </a>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};
